function IconButton({label,children,onClick,primary=false}:any){return <button type="button" title={label} aria-label={label} className={`fg-action-icon ${primary?'primary-button':''}`} onClick={onClick}>{children}</button>}
function useSaved<T,>(key:string,initial:T){const [value,setValue]=useState<T>(()=>{try{return JSON.parse(localStorage.getItem(key)||'null')??initial}catch{return initial}});useEffect(()=>{localStorage.setItem(key,JSON.stringify(value))},[key,value]);return [value,setValue] as const}
function Filter({query,setQuery,status,setStatus,statuses=['Actief','Inactief'],sort,setSort}:any){return <details className="ed-filter"><summary className="fg-action-icon" aria-label="Filters"><SlidersHorizontal size={17}/>{(query||status)&&<i/>}</summary><div className="ed-filter-pop"><Field label="Zoeken"><input placeholder="Zoeken…" value={query} onChange={e=>setQuery(e.target.value)}/></Field><Field label="Status"><select value={status} onChange={e=>setStatus(e.target.value)}><option value="">Alle statussen</option>{statuses.map((s:string)=><option key={s}>{s}</option>)}</select></Field>{setSort&&<Field label="Sortering"><select value={sort} onChange={e=>setSort(e.target.value)}><option value="asc">Naam A–Z</option><option value="desc">Naam Z–A</option></select></Field>}<Button onClick={()=>{setQuery('');setStatus('')}}>Filters wissen</Button></div></details>}
const tone=(s:string)=>s==='Actief'||s==='Goedgekeurd'||s==='Betaald'?'success':s==='Te controleren'||s==='Uitgenodigd'||s==='Vervallen'?'warning':'neutral';

export function OperationalOverview({state,navigate,openSource}:ModuleProps){const attention=state.visits.filter(v=>['Te controleren','Correctie nodig','Teruggestuurd'].includes(v.status));const requestCount=(()=>{try{const rows=JSON.parse(localStorage.getItem('fieldgrid-existing-requests-v1')||'null');return Array.isArray(rows)?rows.filter(r=>r.status!=='Afgewezen').length:3}catch{return 3}})();return <>
<div className="metric-grid mc-operation-kpis"><Metric label="Open aanvragen" value={requestCount} icon={FileText} onClick={()=>navigate('/app/aanvragen')}/><Metric label="Actieve werkbonnen" value={state.visits.filter(v=>!['Gefactureerd','Geannuleerd'].includes(v.status)).length} icon={CalendarDays} onClick={()=>navigate('/app/werkbonnen')}/><Metric label="Aandacht nodig" value={attention.length} icon={ClipboardCheck} onClick={()=>navigate('/app/rapporten')}/></div>
<Panel eyebrow="SIGNALEN" title="Aandacht" action={<button className="text-link ed-link" onClick={()=>navigate('/app/rapporten')}>Open rapportcontrole <ChevronRight size={15}/></button>}><div className="ed-attention">{attention.map(v=><button key={v.id} onClick={()=>openSource(v.id)}><span className="ed-attention-icon"><Bell size={18}/></span><span><strong>{v.id}</strong><small>{v.status} · {v.title}</small></span><ChevronRight size={16}/></button>)}{!attention.length&&<Empty title="Er zijn geen open signalen." text="Ingediende werkrapporten verschijnen hier wanneer er iets te controleren is."/>}</div></Panel>
</>}

