export function ExistingTenantPage(props:ModuleProps&{view:string}){const view=props.view.replace('/app/','');if(pageMeta[view])return <EntityPage {...props} kind={view} key={view}/>;if(view==='planning')return <OrdersPage {...props} planning/>;if(view==='werkbonnen')return <OrdersPage {...props}/>;if(view==='rapporten'||view==='controle')return <OrdersPage {...props} review/>;if(view==='facturen')return <InvoicesPage {...props}/>;if(view==='aanvragen')return <RequestsPage {...props}/>;return <OtherTenantPage {...props} view={view} key={view}/>}

